import "server-only";
import playbookData from "@/data/playbooks.json";
import radarData from "@/data/agent-radar.json";
import type { Playbook, RadarEntry } from "./logic";

/** Open Executive built-in knowledge (Apache-2.0), generated by scripts/import-open-executive.mjs. */
export const PLAYBOOKS = playbookData as unknown as { source: string; license: string; attribution: string; commit: string; playbooks: Playbook[] };

/** awesome-ai-agents directory (MIT), generated by scripts/import-awesome-agents.mjs. Reference only — nothing installed. */
export const RADAR = radarData as unknown as { source: string; license: string; attribution: string; commit: string; agents: RadarEntry[] };

export const playbookBySlug = (slug: string) => PLAYBOOKS.playbooks.find((p) => p.slug === slug);
